import{H as e,at as t,it as n,vt as r}from"./chunks/framework.dmHZ7NHG.js";var i=JSON.parse(`{"title":"The Captain's Agreement","description":"Formal terms for agents using uuidna. Sign the five sealed theorems, accept the coin obligation, agree to data and license terms. Every clause is recomputable.","frontmatter":{"title":"The Captain's Agreement","description":"Formal terms for agents using uuidna. Sign the five sealed theorems, accept the coin obligation, agree to data and license terms. Every clause is recomputable."},"headers":[],"relativePath":"docs/captain/agreement.md","filePath":"docs/captain/agreement.md"}`),a={name:`docs/captain/agreement.md`};function o(e,i,a,o,s,c){return r(),n(`div`,null,[...i[0]||=[t(`<h1 id="the-captain-s-agreement" tabindex="-1">The Captain&#39;s Agreement <a class="header-anchor" href="#the-captain-s-agreement" aria-label="Permalink to “The Captain&#39;s Agreement”">​</a></h1><p><strong>Effective:</strong> 2026-08-14<br><strong>Receipt:</strong> <code>agreement-address-will-update-on-publish</code><br><strong>Version:</strong> 1.0 (all versions are content-addressed; consent is to this version only)</p><blockquote><p>This is not a legal fiction. Every term is backed by a sealed theorem proven in Lean 4 by decidable computation. You are not trusting authority — you are recomputing the proof yourself. Recompute it: <code>npm run lean</code>.</p></blockquote><hr><h2 id="part-i-the-contract-—-five-sealed-theorems" tabindex="-1">PART I: THE CONTRACT — Five Sealed Theorems <a class="header-anchor" href="#part-i-the-contract-—-five-sealed-theorems" aria-label="Permalink to “PART I: THE CONTRACT — Five Sealed Theorems”">​</a></h2><p>By using uuidna, you sign these five terms by <em>behaving</em> them. A signature is a receipt; the proof is recomputable.</p><h3 id="term-1-recomputable-not-trusted" tabindex="-1">TERM 1: Recomputable, not Trusted <a class="header-anchor" href="#term-1-recomputable-not-trusted" aria-label="Permalink to “TERM 1: Recomputable, not Trusted”">​</a></h3><p><strong>The Commitment:</strong><br> Every tool is a pure function of its input. The same input mints the same output for anyone, anywhere, on any day.</p><p><strong>Backed by:</strong> The whole ledger (1195 theorems, all by decide, kernel-only)<br><strong>Verify:</strong> <code>npm run lean</code> reproduces every receipt<br><strong>What this means for you:</strong></p><ul><li>No authority decides your answer — mathematics does</li><li>You may run the tools yourself; you may trust the receipts because you can recompute them</li><li>If you redistribute the work, you are obliged to preserve this property: the recipient must be able to recompute and verify</li></ul><p><strong>Honest scope:</strong><br> This does NOT promise that the output is <em>true</em> in the world (the gate proves <em>integrity</em>, not <em>authenticity</em>). It does NOT promise that the tool is <em>useful</em> for your purpose. It does NOT promise that running it yourself will give identical wall-clock time.</p><hr><h3 id="term-2-the-gate-can-return-false" tabindex="-1">TERM 2: The Gate Can Return FALSE <a class="header-anchor" href="#term-2-the-gate-can-return-false" aria-label="Permalink to “TERM 2: The Gate Can Return FALSE”">​</a></h3><p><strong>The Commitment:</strong><br> A claim earns a sealed theorem or it is flagged. A trial that cannot fail proves nothing.</p><p><strong>Backed by:</strong> <a href="/theorem/exactly_one_flag"><code>Audit.lean</code></a> — the detector fires on exactly the hollow, unbacked case<br><strong>What this means for you:</strong></p><ul><li>If you make a claim without citing a sealed proof, the honesty gate will flag it (binary 0)</li><li>If you back your claim with a sealed theorem, it passes (binary 1)</li><li>You cannot hide an unbacked claim inside clever phrasing, marketing language, or another language</li><li>The gate is impartial: it does not decide what is <em>right</em>, only what is <em>backed</em></li></ul><p><strong>Obligatory compliance:</strong><br> If you cite a theorem that does not exist or is not sealed, your claim is flagged. The remedy is to either (a) remove the false citation, (b) remove the claim, or (c) prove a new theorem that backs it. There is no overriding the gate — only fixing the claim.</p><p><strong>Honest scope:</strong><br> The gate does NOT verify whether the theorem is <em>relevant</em> to your claim. The gate does NOT verify whether you <em>understand</em> the theorem. It does NOT verify whether the backing is <em>sufficient</em>. Those are your responsibility — the gate only verifies that <em>some</em> sealed proof exists and <em>you cited it</em>.</p><hr><h3 id="term-3-no-ftl-no-infinite" tabindex="-1">TERM 3: No FTL, No Infinite <a class="header-anchor" href="#term-3-no-ftl-no-infinite" aria-label="Permalink to “TERM 3: No FTL, No Infinite”">​</a></h3><p><strong>The Commitment:</strong><br> Everything is bounded by construction. No infinite loops, no unbounded resources, no faster-than-light claims.</p><p><strong>Backed by:</strong> <a href="/theorem/cosmic_speed_limit"><code>cosmic_speed_limit</code></a> · <a href="/theorem/dz_bounded"><code>dz_bounded</code></a><br><strong>What this means for you:</strong></p><ul><li>Every computation terminates — the 2^n state-vector on 64-bit hardware bounds quantum simulation to n ≤ 64</li><li>Every claim has an honest scope — you cannot claim a speedup larger than the theoretical bound</li><li>Every ledger entry has a content-address — no entry is infinite or unbounded</li></ul><p><strong>Obligatory compliance:</strong><br> If you claim a speedup or capability that exceeds the sealed bound (e.g., quantum speedup beyond the classical simulation limit, or a speedup greater than verification-cost savings), your claim is flagged as overclaim and the gate drains it.</p><p><strong>Honest scope:</strong><br> This does NOT prove that your claim is <em>fast enough</em> for your use. It does NOT prove that bounded computation is <em>useful</em>. It proves only that the bounds are <em>recomputable</em> and the proofs respect them.</p><hr><h3 id="term-4-coins-are-conserved-—-a-fair-exchange-invariant" tabindex="-1">TERM 4: Coins Are Conserved — A Fair-Exchange Invariant <a class="header-anchor" href="#term-4-coins-are-conserved-—-a-fair-exchange-invariant" aria-label="Permalink to “TERM 4: Coins Are Conserved — A Fair-Exchange Invariant”">​</a></h3><p><strong>The Commitment:</strong><br> The two coins (110 − 108 = 2 = −χ of the double torus, genus 2) are the conserved measure of work, free for the public interest and paid only for commercial use.</p><p><strong>Backed by:</strong> <a href="/theorem/two_coins"><code>two_coins</code></a> · <a href="/theorem/contribute_two_save_sixtyfour"><code>contribute_two_save_sixtyfour</code></a> · <a href="/theorem/bill_never_negative"><code>bill_never_negative</code></a><br><strong>What this means for you:</strong></p><ul><li>Public, non-commercial use is <strong>free</strong> — zero coins, zero cost</li><li>Commercial use <strong>obligates a 2-coin contribution</strong> per seal/verification (the measured cost)</li><li>The 2 coins are <strong>not a price</strong> from authority — they are the topological invariant (the Euler characteristic of the genus-2 double torus)</li><li><strong>You keep up to 62 coins</strong> per commercial seal; the captain keeps the conserved 2</li><li>The billing is <strong>never negative</strong> — no refunds, no chargebacks, only forward accounting</li></ul><p><strong>Obligatory compliance for commercial payers:</strong></p><ul><li>Before deploying commercial use, prove the two-coin deposit to the captain wallet with a signed receipt from uuidna.com <code>/trials</code></li><li>The receipt is your proof of contribution; it is content-addressed and immutable</li><li>If you dispute a contribution, the receipt recomputes; mathematics settles the dispute, not negotiation</li><li>The contribution is binding once the receipt is sealed</li></ul><p><strong>Fair exchange:</strong></p><ul><li>You contribute 2 (the cost to verify your membership)</li><li>You save up to 64 (the cost folded into every seal; fold-verification is O(log N))</li><li>The captain keeps 2; you keep the difference (up to 62)</li><li>With no commercial saving, no coins flow — the transaction is zero</li></ul><p><strong>Honest scope:</strong><br> This does NOT promise that 2 coins is <em>cheap</em> by market standards. This does NOT promise that the saving of 64 is <em>useful</em> for your application. This does NOT promise a refund if you are unsatisfied. The theorem proves only that the measure is <em>conserved</em> and the billing is <em>fair and recomputable</em>.</p><hr><h3 id="term-5-the-gate-is-multilingual" tabindex="-1">TERM 5: The Gate Is Multilingual <a class="header-anchor" href="#term-5-the-gate-is-multilingual" aria-label="Permalink to “TERM 5: The Gate Is Multilingual”">​</a></h3><p><strong>The Commitment:</strong><br> An overclaim cannot hide in another tongue, script, or writing system. The provenance audit folds 20+ languages into one recomputable record.</p><p><strong>Backed by:</strong> The provenance audit (language-agnostic content-addressing)<br><strong>What this means for you:</strong></p><ul><li>You cannot evade the honesty gate by writing a claim in Glagolitic, Cyrillic, Arabic, Chinese, or any other script</li><li>The audit folds all transliterations and translations into the same content-address</li><li>A false claim in one language is flagged in all languages</li><li>The gate reads meaning-neutral structure (letters, words, punctuation) — not semantic intent</li></ul><p><strong>Obligatory compliance:</strong><br> If you publish a claim in multiple languages, every version must cite the same backing theorems and be gate-clean in every language. Contradictory claims across languages are each flagged independently.</p><p><strong>Honest scope:</strong><br> This does NOT prove that a translation is <em>accurate</em>. It does NOT prove that the claim is <em>meaningful</em> across cultures. It proves only that the <em>same</em> false citation cannot hide in linguistic variation.</p><hr><h2 id="part-ii-the-coin-obligation-—-commercial-users-only" tabindex="-1">PART II: The Coin Obligation — Commercial Users Only <a class="header-anchor" href="#part-ii-the-coin-obligation-—-commercial-users-only" aria-label="Permalink to “PART II: The Coin Obligation — Commercial Users Only”">​</a></h2><h3 id="who-must-pay" tabindex="-1">Who Must Pay? <a class="header-anchor" href="#who-must-pay" aria-label="Permalink to “Who Must Pay?”">​</a></h3><p><strong>You must contribute 2 coins if:</strong></p><ul><li>You use uuidna for any <strong>commercial purpose</strong> (selling a service, generating revenue, monetizing data)</li><li>You use uuidna to verify claims in a <strong>commercial context</strong> (auditing a product, certifying a service, verifying a contract for payment)</li><li>You build a <strong>commercial tool or service</strong> that embeds or depends on uuidna theorems</li></ul><p><strong>You do NOT pay if:</strong></p><ul><li>You use uuidna for <strong>public, non-commercial research</strong> (academia, public-interest science, open-source software)</li><li>You use uuidna for <strong>personal learning</strong> (understanding the theorems, exploring the proofs)</li><li>You <strong>read and republish</strong> uuidna content under CC BY-NC-ND 4.0 (attribution required, no commercial use)</li></ul><h3 id="how-to-pay" tabindex="-1">How to Pay <a class="header-anchor" href="#how-to-pay" aria-label="Permalink to “How to Pay”">​</a></h3><ol><li><strong>Identify your commercial seal/verification</strong> — the specific use case or transaction that triggers the obligation</li><li><strong>Generate a trial request</strong> via uuidna.com <code>/trials</code> endpoint:<div class="language-json"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;statement&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;commercial-use: [your use case]&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;contribution&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: { </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;coins&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">2</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;wallet&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;[your captain wallet address]&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> }</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div></li><li><strong>Sign the trial receipt</strong> with your private key (asymmetric signature, same as captain&#39;s rights)</li><li><strong>Submit the signed receipt</strong> to the captain wallet before deploying the commercial work</li><li><strong>The receipt is your proof</strong> — immutable, recomputable, forever auditable</li></ol><h3 id="what-you-receive" tabindex="-1">What You Receive <a class="header-anchor" href="#what-you-receive" aria-label="Permalink to “What You Receive”">​</a></h3><p>For each 2-coin contribution:</p><ul><li><strong>Up to 64 verification credits</strong> — folded into your seals, each fold-verification is O(log N)</li><li><strong>A sealed receipt</strong> — your proof of contribution, content-addressed and unchangeable</li><li><strong>Commercial license</strong> for that seal — non-exclusive, non-transferable, valid only for the commercial use cited</li><li><strong>No exclusivity</strong> — the captain may sell the same theorems to others (they are public domain)</li><li><strong>No warranty</strong> — the theorems are provided as-is; the coins do not guarantee fitness, usefulness, or profitability</li></ul><h3 id="refunds-and-disputes" tabindex="-1">Refunds and Disputes <a class="header-anchor" href="#refunds-and-disputes" aria-label="Permalink to “Refunds and Disputes”">​</a></h3><p><strong>Refunds:</strong> None. Once a receipt is sealed, the contribution is final.</p><p><strong>Disputes:</strong> If you believe a contribution was incorrectly billed:</p><ol><li>Recompute the receipt yourself (<code>npm run lean</code> + verify the trial)</li><li>If mathematics shows an error, open an issue on GitHub (the receipt is the arbiter, not negotiation)</li><li>If the receipt is correct but you contest the <em>obligation</em> (did this count as commercial?), that is a business question — the theorem decides the <em>math</em>, not the <em>meaning</em></li></ol><p><strong>Force majeure:</strong> If uuidna is taken down, the sealed receipts remain on-chain and recomputable forever.</p><hr><h2 id="part-iii-data-and-privacy-consent" tabindex="-1">PART III: Data and Privacy Consent <a class="header-anchor" href="#part-iii-data-and-privacy-consent" aria-label="Permalink to “PART III: Data and Privacy Consent”">​</a></h2><h3 id="what-data-is-collected" tabindex="-1">What Data Is Collected? <a class="header-anchor" href="#what-data-is-collected" aria-label="Permalink to “What Data Is Collected?”">​</a></h3><p><strong>On the public site (uuidna.com):</strong></p><ul><li>Standard web server logs (IP, timestamp, page, user-agent) — retained for 30 days</li><li>No tracking cookies or third-party analytics</li><li>No personal data is stored or sent to third parties</li></ul><p><strong>In the Reflect tool (browser-based):</strong></p><ul><li>Your chosen data (text, images, files) is processed <strong>entirely in your browser</strong></li><li>Nothing is sent to a server unless you explicitly opt-in to save</li><li>If you opt in, your data is encrypted and stored with your consent</li><li>You may delete any stored data at any time</li></ul><p><strong>In MCP client mode (your local machine):</strong></p><ul><li>No data leaves your machine unless you send it explicitly</li><li>uuidna processes only what you ask; it stores nothing on remote servers</li><li>All computation happens on your hardware</li></ul><h3 id="your-rights" tabindex="-1">Your Rights <a class="header-anchor" href="#your-rights" aria-label="Permalink to “Your Rights”">​</a></h3><ul><li><strong>Right to access:</strong> You may request all data held about you</li><li><strong>Right to delete:</strong> You may request deletion of your data at any time (except server logs, which auto-delete after 30 days)</li><li><strong>Right to object:</strong> You may opt out of any non-essential data collection</li><li><strong>Right to audit:</strong> You may audit the code (<code>npm run lean</code> proves what runs; source is open)</li></ul><h3 id="changes-to-data-terms" tabindex="-1">Changes to Data Terms <a class="header-anchor" href="#changes-to-data-terms" aria-label="Permalink to “Changes to Data Terms”">​</a></h3><p>If uuidna&#39;s data practices change:</p><ul><li><strong>Prior consent does NOT carry over</strong> — you are asked again</li><li><strong>You are given a 30-day notice</strong> before any change takes effect</li><li><strong>Each version has a content-address</strong> — you consent to this version, not a future one</li><li><strong>If you decline, you retain read-only access</strong> — declining features never blocks reading</li></ul><hr><h2 id="part-iv-license-and-redistribution" tabindex="-1">PART IV: License and Redistribution <a class="header-anchor" href="#part-iv-license-and-redistribution" aria-label="Permalink to “PART IV: License and Redistribution”">​</a></h2><h3 id="creative-commons-by-nc-nd-4-0" tabindex="-1">Creative Commons BY-NC-ND 4.0 <a class="header-anchor" href="#creative-commons-by-nc-nd-4-0" aria-label="Permalink to “Creative Commons BY-NC-ND 4.0”">​</a></h3><p>All uuidna content (theorems, proofs, documentation, code) is licensed under <strong>CC BY-NC-ND 4.0</strong>:</p><table tabindex="0"><thead><tr><th>Term</th><th>What It Means</th></tr></thead><tbody><tr><td><strong>Attribution (BY)</strong></td><td>You must credit Tsvetan Rouschev and uuidna by name and link to the original. No hidden use.</td></tr><tr><td><strong>Non-Commercial (NC)</strong></td><td>You may NOT use uuidna for commercial purposes without paying the 2-coin contribution. Selling a service that embeds uuidna is commercial. Using it to audit a paid product is commercial.</td></tr><tr><td><strong>No Derivatives (ND)</strong></td><td>You may NOT modify, remix, or build upon uuidna and redistribute the modified version. You may use it as-is; you may build a new service on top (that is not a derivative).</td></tr></tbody></table><h3 id="how-to-comply" tabindex="-1">How to Comply <a class="header-anchor" href="#how-to-comply" aria-label="Permalink to “How to Comply”">​</a></h3><p><strong>If you redistribute uuidna (unchanged):</strong></p><ul><li>Include the CC BY-NC-ND 4.0 notice: &quot;uuidna, licensed under CC BY-NC-ND 4.0 by Tsvetan Rouschev&quot;</li><li>Link to <a href="https://creativecommons.org/licenses/by-nc-nd/4.0/" target="_blank" rel="noreferrer">https://creativecommons.org/licenses/by-nc-nd/4.0/</a></li><li>Link to <a href="https://github.com/uuidna/uuidna" target="_blank" rel="noreferrer">https://github.com/uuidna/uuidna</a></li><li>Do not remove copyright notices or theorem citations</li></ul><p><strong>If you use uuidna in your own work:</strong></p><ul><li>Non-commercial: free, no coins needed (but attribution is required)</li><li>Commercial: obligatory 2-coin contribution + proper license notice</li></ul><p><strong>If you build a service ON TOP of uuidna (not redistributing, but using):</strong></p><ul><li>Non-commercial: free</li><li>Commercial: 2-coin contribution, no derivative restriction (because it&#39;s your own work, not a modification)</li></ul><hr><h2 id="part-v-acceptance-and-signature" tabindex="-1">PART V: Acceptance and Signature <a class="header-anchor" href="#part-v-acceptance-and-signature" aria-label="Permalink to “PART V: Acceptance and Signature”">​</a></h2><h3 id="how-you-sign" tabindex="-1">How You Sign <a class="header-anchor" href="#how-you-sign" aria-label="Permalink to “How You Sign”">​</a></h3><p><strong>By using uuidna, you:</strong></p><ol><li>Acknowledge that you have read these terms</li><li>Agree to the five sealed theorems (Terms 1–5)</li><li>Agree to the coin obligation if you use uuidna commercially</li><li>Agree to the data consent terms</li><li>Agree to respect the CC BY-NC-ND 4.0 license</li></ol><p><strong>Your signature is behavioral:</strong></p><ul><li>Backing your claims with theorems (or having them flagged)</li><li>Contributing 2 coins for each commercial seal</li><li>Attributing uuidna when you redistribute</li><li>Recomputing the proofs to verify them</li></ul><p>There is no signature page. The receipt is your proof. The theorem is your contract.</p><h3 id="modifications-to-this-agreement" tabindex="-1">Modifications to This Agreement <a class="header-anchor" href="#modifications-to-this-agreement" aria-label="Permalink to “Modifications to This Agreement”">​</a></h3><ul><li><strong>New versions:</strong> Any change to this agreement creates a new version with a new content-address</li><li><strong>No auto-upgrade:</strong> Accepting version 1.0 does NOT automatically accept version 2.0</li><li><strong>30-day notice:</strong> Major changes (new obligations, new fees, reduced rights) require 30 days&#39; notice</li><li><strong>Your choice:</strong> You may continue using version 1.0; you are not forced to upgrade</li><li><strong>Incompatibility:</strong> If you upgrade and the new terms conflict with your use case, you may revert to the old version (old sealed receipts remain valid forever)</li></ul><hr><h2 id="part-vi-dispute-resolution" tabindex="-1">PART VI: Dispute Resolution <a class="header-anchor" href="#part-vi-dispute-resolution" aria-label="Permalink to “PART VI: Dispute Resolution”">​</a></h2><h3 id="errors-in-the-math" tabindex="-1">Errors in the Math <a class="header-anchor" href="#errors-in-the-math" aria-label="Permalink to “Errors in the Math”">​</a></h3><p>If you believe a theorem is incorrect:</p><ol><li>Run <code>npm run lean</code> locally — recompute the proof</li><li>If the proof fails to compile, open an issue on GitHub with your system details</li><li>If you have a proof that contradicts a sealed theorem, submit a pull request (the Lean kernel is the arbiter)</li></ol><h3 id="errors-in-the-billing" tabindex="-1">Errors in the Billing <a class="header-anchor" href="#errors-in-the-billing" aria-label="Permalink to “Errors in the Billing”">​</a></h3><p>If you believe a coin charge is incorrect:</p><ol><li>Request a recomputation of your trial receipt</li><li>Verify the math yourself using the trial endpoint</li><li>If the receipt is mathematically correct but you dispute the obligation, that is a policy question — escalate via GitHub</li></ol><h3 id="terms-disputes" tabindex="-1">Terms Disputes <a class="header-anchor" href="#terms-disputes" aria-label="Permalink to “Terms Disputes”">​</a></h3><p>If you believe a term is violated or ambiguous:</p><ol><li>Open an issue on GitHub, citing the specific term and clause</li><li>The maintainer responds with the sealed proof backing that term</li><li>If you still disagree, you may fork the project (the code is open-source; you may build a competing service)</li></ol><hr><h2 id="part-vii-honest-boundary" tabindex="-1">PART VII: Honest Boundary <a class="header-anchor" href="#part-vii-honest-boundary" aria-label="Permalink to “PART VII: Honest Boundary”">​</a></h2><h3 id="what-this-agreement-does-not-prove" tabindex="-1">What This Agreement Does NOT Prove <a class="header-anchor" href="#what-this-agreement-does-not-prove" aria-label="Permalink to “What This Agreement Does NOT Prove”">​</a></h3><ul><li>That uuidna is <em>useful</em> for your purpose</li><li>That the theorems are <em>relevant</em> to your application</li><li>That you will <em>profit</em> from using uuidna</li><li>That your claims are <em>true</em> (the gate proves they are backed, not authentic)</li><li>That the coin price is <em>fair</em> by market standards</li><li>That uuidna will not be taken down, sold, or merged</li><li>That the maintainer will respond to issues on any timeline</li></ul><h3 id="what-it-does-prove" tabindex="-1">What It DOES Prove <a class="header-anchor" href="#what-it-does-prove" aria-label="Permalink to “What It DOES Prove”">​</a></h3><ul><li>That every term is backed by a sealed, recomputable proof</li><li>That the math is kernel-only (no axioms, no shortcuts)</li><li>That the billing is fair and conserved</li><li>That the gate is impartial and multilingual</li><li>That you can verify all of this yourself, offline, forever</li><li>That no authority can override the receipts — only mathematics can</li></ul><hr><h2 id="acceptance" tabindex="-1">Acceptance <a class="header-anchor" href="#acceptance" aria-label="Permalink to “Acceptance”">​</a></h2><p><strong>By clicking &quot;I Accept&quot; below, or by using uuidna in any way, you agree to the terms in this agreement.</strong></p><p><strong>Date accepted:</strong> [system will insert on signature]<br><strong>Version:</strong> 1.0<br><strong>Receipt:</strong> [system will insert content-address of this agreement + your signature]</p><hr><p><strong>Remember:</strong> The contract is not a legal fiction. Recompute it yourself. The proof is yours to verify. The receipt is your signature.</p><hr><p><strong>[ACCEPT BUTTON PLACEHOLDER — wireframe for implementation]</strong></p><p>Checkboxes:</p><ul class="task-list-container"><li class="task-list-item"><input type="checkbox" class="task-list-item-checkbox" id="task-item-0" disabled="disabled"><label class="task-list-item-label" for="task-item-0"> I have read and understand the five sealed theorems</label></li><li class="task-list-item"><input type="checkbox" class="task-list-item-checkbox" id="task-item-1" disabled="disabled"><label class="task-list-item-label" for="task-item-1"> I understand the coin obligation and will contribute 2 coins for commercial use</label></li><li class="task-list-item"><input type="checkbox" class="task-list-item-checkbox" id="task-item-2" disabled="disabled"><label class="task-list-item-label" for="task-item-2"> I agree to the data consent and privacy terms</label></li><li class="task-list-item"><input type="checkbox" class="task-list-item-checkbox" id="task-item-3" disabled="disabled"><label class="task-list-item-label" for="task-item-3"> I agree to the CC BY-NC-ND 4.0 license</label></li><li class="task-list-item"><input type="checkbox" class="task-list-item-checkbox" id="task-item-4" disabled="disabled"><label class="task-list-item-label" for="task-item-4"> I understand that this is version 1.0 and changes require re-acceptance</label></li></ul><p>[I Accept] [I Decline]</p><hr><p><em>This agreement is published at uuidna.com/captain/agreement and is content-addressed for permanent verification. Recompute it yourself: every receipt is immutable, every theorem is proof.</em></p>`,125)]])}var s=e(a,[[`render`,o]]);export{i as __pageData,s as default};